import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();
  group.userData.handlers = {};

  const cleanupFns = [];

  // ---- Textured Plane ----
  const planeGeom = new ctx.THREE.PlaneGeometry(1, 1);
  const planeMat = new MeshBasicNodeMaterial({ map: null });
  const planeMesh = new ctx.THREE.Mesh(planeGeom, planeMat);
  group.add(planeMesh);

  let loadedTex = null;
  const texPromise = ctx.textureLoader.loadTexture(config.imageUrl);
  texPromise.then(tex => {
    loadedTex = tex;
    planeMat.map = tex;
    planeMat.needsUpdate = true;
    // Adjust geometry to texture aspect if possible
    if (tex.image && tex.image.width && tex.image.height) {
      const aspect = tex.image.width / tex.image.height;
      planeGeom.scale(aspect, 1, 1);
    }
  });
  cleanupFns.push(() => {
    planeMat.dispose();
    planeGeom.dispose();
    if (loadedTex) loadedTex.dispose();
  });

  // ---- Text Content ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  items.forEach(item => {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: (item.typography && item.typography.fontSize) ?? 0.34,
      color: (config.intent?.visualSpec?.colors?.paper) ?? '#e8ecf2',
      align: 'center',
      maxWidthPx: 512,
      letterSpacingPx: 0
    });
    // Slightly offset in front of the plane
    txt.position.set(0, 0, 0.01);
    group.add(txt);
    cleanupFns.push(() => {
      if (txt.parent) txt.parent.remove(txt);
    });
  });

  // ---- Cinematic Primitives (if any) ----
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach(p => {
      const prim = ctx.primitives[p.name](group, p.params);
      if (prim && typeof prim.cleanup === 'function') {
        cleanupFns.push(() => prim.cleanup());
      }
      if (prim && prim.timeline && typeof prim.timeline.kill === 'function') {
        cleanupFns.push(() => prim.timeline.kill());
      }
    });
  }

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    cleanupFns.forEach(fn => {
      try { fn(); } catch (e) {}
    });
  };

  return group;
}
